//! Compile-time coverage for the code generated by `#[plugin]`.
//!
//! The expansion tests in the crate verify classification; this test makes the generated
//! `Plugin` implementation itself compile for the edge cases that need special handling.

use zeta_plugin::argh::{ArgsInfo, FromArgs};
use zeta_plugin::prelude::*;
use zeta_plugin::{Client, Error};

/// A plugin whose command and URL handler are gated out.
#[derive(Default)]
struct Gated;

#[plugin(name = "gated", urls(any))]
impl Gated {
    #[cfg(any())]
    #[command(".gated", "A command compiled out by cfg")]
    async fn gated(&self, _: &Context, _: &Client, _: &str) -> Result<(), Error> {
        Ok(())
    }

    #[cfg(any())]
    #[handler(url)]
    async fn url(&self, _: &Context, _: &Client, _: &UrlEvent) -> Result<(), Error> {
        Ok(())
    }
}

/// A plugin with a zero-argument helper named `new`; it is not the plugin constructor.
#[derive(Default)]
struct Helper;

#[plugin(name = "helper")]
impl Helper {
    const fn new() -> Self {
        Self
    }

    #[command(".helper", "A helper constructor")]
    async fn helper(&self, _: &Context, _: &Client, _: &str) -> Result<(), Error> {
        Ok(())
    }
}

/// Options for the free-form `words` command.
#[derive(ArgsInfo, FromArgs)]
struct WordsOptions {
    /// the words to echo
    #[argh(positional)]
    #[allow(dead_code)]
    words: Vec<String>,
}

/// A plugin using the `words` argument mode.
#[derive(Default)]
struct Words;

#[plugin(name = "words")]
impl Words {
    #[command(".words", "Echo the words", args = WordsOptions, words)]
    async fn words(
        &self,
        _: &Context,
        _: &Client,
        _: &str,
        _options: WordsOptions,
    ) -> Result<(), Error> {
        Ok(())
    }
}

#[test]
fn helper_constructor_remains_callable() {
    let _ = Helper::new();
}
